// Do not edit this file as it will be overwritten if HAMR codegen is rerun

use crate::bridge::seL4_MAVLinkFirewall_MAVLinkFirewall_api::*;
use crate::bridge::seL4_MAVLinkFirewall_MAVLinkFirewall_GUMBOX as GUMBOX;
use data::*;
use super::seL4_MAVLinkFirewall_MAVLinkFirewall_app::seL4_MAVLinkFirewall_MAVLinkFirewall;

// Instance of the R2U2 monitor.
static mut R2U2_MONITOR: Option<R2U2Monitor> = None;

// Specifications without an alert mapping are logged after every monitor step.
const R2U2_LOGGED_SPECS: [(usize, &'static str); 1] = [
    (0, "hlr_30_llr_15_16_recovery_deadline")
];

struct R2U2Monitor {
  monitor: r2u2_core::Monitor,
  // Cache latest verdict (if applicable) per C2PO specification between monitor steps.
  verdict_cache: [Option<r2u2_core::r2u2_verdict>; 1],
}

impl R2U2Monitor {
  fn new() -> Self {
    Self {
      monitor: r2u2_core::Monitor::default(),
      verdict_cache: [None; 1],
    }
  }
}

impl seL4_MAVLinkFirewall_MAVLinkFirewall {
  pub fn r2u2_monitor_initialize(&mut self)
  {
    let mut r2u2_monitor = R2U2Monitor::new();
    r2u2_core::update_binary_file(include_bytes!("spec.bin"), &mut r2u2_monitor.monitor);
    unsafe { R2U2_MONITOR = Some(r2u2_monitor); }
  }

  pub fn r2u2_monitor_pre_timeTriggered<API: seL4_MAVLinkFirewall_MAVLinkFirewall_Full_Api> (
    &mut self,
    api: &seL4_MAVLinkFirewall_MAVLinkFirewall_Application_Api<API>)
  {
    let current_mode = api.peek_current_mode();

    let r2u2_monitor = unsafe {
      R2U2_MONITOR.as_mut().expect("R2U2 monitor used before initialization")
    };

    r2u2_core::load_int_signal(&mut r2u2_monitor.monitor, 0, (self.rejected_count) as i32); // Loading signal in_rejected_count into index 0
    r2u2_core::load_int_signal(&mut r2u2_monitor.monitor, 1, (GUMBOX::error_threshold()) as i32); // Loading signal fn_error_threshold into index 1
    r2u2_core::load_int_signal(&mut r2u2_monitor.monitor, 3, current_mode as i32); // Loading enum signal api_current_mode into index 3
  }

  pub fn r2u2_monitor_post_timeTriggered<API: seL4_MAVLinkFirewall_MAVLinkFirewall_Full_Api> (
    &mut self,
    api: &mut seL4_MAVLinkFirewall_MAVLinkFirewall_Application_Api<API>)
  {
    let error_status = api.peek_error_status();

    let r2u2_monitor = unsafe {
      R2U2_MONITOR.as_mut().expect("R2U2 monitor used before initialization")
    };

    r2u2_core::load_bool_signal(&mut r2u2_monitor.monitor, 2, error_status); // Loading signal api_error_status into index 2

    r2u2_core::monitor_step(&mut r2u2_monitor.monitor);
    let r2u2_time_stamp = r2u2_monitor.monitor.time_stamp;
    // Expire cached verdicts before applying this step's new outputs.
    for verdict in r2u2_monitor.verdict_cache.iter_mut() {
        if verdict.is_some() && r2u2_time_stamp > verdict.unwrap().time {
            *verdict = None;
        }
    }
    // Keep false verdicts visible when a later output replaces the cache entry.
    let output_buffer = r2u2_core::get_output_buffer(&r2u2_monitor.monitor);
    let verdict_cache = &mut r2u2_monitor.verdict_cache;
    let mut false_verdict_seen = [false; 1];
    for out in output_buffer {
        let spec_num = out.spec_num as usize;
        if !out.verdict.truth {
            false_verdict_seen[spec_num] = true;
        }
        verdict_cache[spec_num] = Some(out.verdict);
    }
    // Report one status for each specification without an alert port.
    for (spec_num, spec_name) in R2U2_LOGGED_SPECS {
        let status = match r2u2_monitor.verdict_cache[spec_num] {
            Some(verdict) => {
                let truth = verdict.truth && !false_verdict_seen[spec_num];
                if truth { "true" } else { "false" }
            },
            None => "unknown",
        };
        log::info!("{} is currently {}", spec_name, status);
    }
  }
}
